CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE "user" (id text PRIMARY KEY,name text NOT NULL,email text NOT NULL UNIQUE,"emailVerified" boolean NOT NULL DEFAULT false,image text,"twoFactorEnabled" boolean DEFAULT false,"createdAt" timestamp NOT NULL DEFAULT now(),"updatedAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE session (id text PRIMARY KEY,token text UNIQUE NOT NULL,"expiresAt" timestamp NOT NULL,"ipAddress" text,"userAgent" text,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,"createdAt" timestamp NOT NULL DEFAULT now(),"updatedAt" timestamp NOT NULL DEFAULT now());
CREATE INDEX ON session("userId");
CREATE TABLE account (id text PRIMARY KEY,"accountId" text NOT NULL,"providerId" text NOT NULL,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,"accessToken" text,"refreshToken" text,"idToken" text,"accessTokenExpiresAt" timestamp,"refreshTokenExpiresAt" timestamp,scope text,password text,"createdAt" timestamp NOT NULL DEFAULT now(),"updatedAt" timestamp NOT NULL DEFAULT now());
CREATE INDEX ON account("userId");
CREATE TABLE verification (id text PRIMARY KEY,identifier text NOT NULL,value text NOT NULL,"expiresAt" timestamp NOT NULL,"createdAt" timestamp NOT NULL DEFAULT now(),"updatedAt" timestamp NOT NULL DEFAULT now());
CREATE INDEX ON verification(identifier);
CREATE TABLE "twoFactor" (id text PRIMARY KEY,secret text NOT NULL,"backupCodes" text NOT NULL,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,verified boolean DEFAULT true,"failedVerificationCount" integer DEFAULT 0,"lockedUntil" timestamp);
CREATE INDEX ON "twoFactor"("userId");
CREATE TABLE "rateLimit" (id text PRIMARY KEY,key text UNIQUE NOT NULL,count integer NOT NULL,"lastRequest" text NOT NULL);
CREATE TABLE security_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id text REFERENCES "user"(id),event text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workspaces(id uuid PRIMARY KEY,name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL,currency text NOT NULL DEFAULT 'BRL',timezone text NOT NULL DEFAULT 'America/Fortaleza',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE companies(id uuid PRIMARY KEY,org_id uuid NOT NULL REFERENCES organizations(id),parent_id uuid,name text NOT NULL,kind text NOT NULL CHECK(kind IN ('company','brand','unit')),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,org_id),FOREIGN KEY(parent_id,org_id) REFERENCES companies(id,org_id));
CREATE TABLE members(id uuid PRIMARY KEY,org_id uuid NOT NULL REFERENCES organizations(id),user_id text NOT NULL REFERENCES "user"(id),role text NOT NULL CHECK(role IN ('owner','admin','member')),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','deactivated')),job_title text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,user_id));
CREATE TABLE templates(id text PRIMARY KEY,version integer NOT NULL,modules jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE projects(id uuid PRIMARY KEY,org_id uuid NOT NULL REFERENCES organizations(id),company_id uuid,name text NOT NULL,description text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),currency text NOT NULL DEFAULT 'BRL',timezone text NOT NULL DEFAULT 'America/Fortaleza',template_id text NOT NULL REFERENCES templates(id),template_version integer NOT NULL,modules jsonb NOT NULL,created_by text NOT NULL REFERENCES "user"(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,org_id),FOREIGN KEY(company_id,org_id) REFERENCES companies(id,org_id));
CREATE TABLE grants(id uuid PRIMARY KEY,org_id uuid NOT NULL,project_id uuid NOT NULL,user_id text NOT NULL,role text NOT NULL,permissions jsonb NOT NULL,source text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','revoked')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,user_id),FOREIGN KEY(project_id,org_id) REFERENCES projects(id,org_id),FOREIGN KEY(org_id,user_id) REFERENCES members(org_id,user_id));
CREATE TABLE invitations(id uuid PRIMARY KEY,org_id uuid NOT NULL,project_id uuid NOT NULL,email text NOT NULL,role text NOT NULL,permissions jsonb NOT NULL,token_hash text UNIQUE NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','cancelled')),expires_at timestamptz NOT NULL,created_by text NOT NULL REFERENCES "user"(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,org_id) REFERENCES projects(id,org_id));
CREATE TABLE audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,org_id uuid NOT NULL REFERENCES organizations(id),actor_id text NOT NULL REFERENCES "user"(id),action text NOT NULL,target_id text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON projects(org_id); CREATE INDEX ON grants(user_id,org_id,status); CREATE INDEX ON invitations(org_id,status); CREATE INDEX ON audit_logs(org_id,created_at DESC);
